<form class="search"><input type="hidden" name="type" value="<?=$type?>"><label>ค้นหาตามชื่อ<?=$isShop?'ร้านค้า':'สำนักพิมพ์'?></label><div class="search-box"><input name="q" value="<?=htmlspecialchars($keyword)?>" placeholder="พิมพ์ชื่อที่คุณกำลังตามหา..."><button>⌕</button></div></form>
<div class="results"><span>แสดงผลลัพธ์ที่ <?=$total?($offset+1).'–'.min($offset+$perPage,$total):'0'?> จากทั้งหมด <?=number_format($total)?> รายการ</span><form class="sort"><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="q" value="<?=htmlspecialchars($keyword)?>"><label>จัดเรียงตาม:</label><select name="sort" onchange="this.form.submit()"><option value="popular" <?=$sort==='popular'?'selected':''?>>ยอดนิยม</option><option value="books" <?=$sort==='books'?'selected':''?>>จำนวนหนังสือ</option><option value="newest" <?=$sort==='newest'?'selected':''?>>มาใหม่</option><option value="name" <?=$sort==='name'?'selected':''?>>ชื่อ</option></select></form></div>
<div class="grid"><?php if(!$rows):?><p class="empty">ไม่พบข้อมูลที่ค้นหา</p><?php else:foreach($rows as $r){$partner=['id'=>(int)$r['partner_id'],'type'=>$type,'name'=>wanawanSellerName($r['partner_name'],$type),'image'=>pImage($r['profile_image']),'followers'=>$r['followers_count'],'books_count'=>$r['books_count'],'profile_url'=>'/pages/partner_detail.php?type='.$type.'&id='.(int)$r['partner_id']];require __DIR__.'/../components/partner_card.php';}endif;?></div>
<?php if($pages>1):?><nav class="pagination"><?php for($p=1;$p<=$pages;$p++):?><a class="<?=$p===$page?'active':''?>" href="<?=htmlspecialchars(pQuery(['page'=>$p]))?>"><?=$p?></a><?php endfor;?></nav><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?></body></html>
